{
  "cvars": {
    "ivs": [
      {
        "description": "Name femininity (continuous): human raters' masculinity-femininity index for the hurricane name, standardized (higher = more feminine). Used to test whether more-feminine names are associated with worse outcomes (interpreted as evidence of fewer precautions taken).",
        "columns": [
          "masfem_z"
        ]
      },
      {
        "description": "Name gender (binary): binary indicator for female name (0=male, 1=female). Included as an alternative / complementary independent variable to test effects of categorical female vs. male names.",
        "columns": [
          "gender_mf"
        ]
      }
    ],
    "dv": {
      "description": "Fatalities caused by the hurricane (count). Interpreted as an outcome reflecting, in part, the degree of precautionary measures taken by the public; modeled as a count (negative-binomial GLM) to account for over-dispersion.",
      "columns": [
        "alldeaths"
      ]
    },
    "controls": [
      {
        "description": "Maximum sustained wind speed at landfall (mph). Controls for storm intensity.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "wind"
        ]
      },
      {
        "description": "Saffir\u2013Simpson category (1-5). Controls for storm intensity/force.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "category"
        ]
      },
      {
        "description": "Minimum central pressure at landfall (hPa). Controls for storm intensity (lower = stronger); renamed to avoid Python built-in name conflicts.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "min_pressure"
        ]
      },
      {
        "description": "Year of the hurricane. Controls for temporal trends (warning systems, infrastructure, population changes).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "year"
        ]
      },
      {
        "description": "Elapsed years since the hurricane (used in dataset). Additional temporal control that can capture time-since-event related reporting differences.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "elapsedyrs"
        ]
      },
      {
        "description": "Data source (categorical). Controls for differences in reporting/collection across sources (included as categorical variable C(source) in the model).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "source"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    # Make a copy to avoid modifying the original\n    df = df.copy()\n\n    # ----------------------\n    # Required columns and basic cleaning\n    # ----------------------\n    # Keep rows with non-missing dependent variable and main IVs\n    required_cols = ['alldeaths', 'masfem', 'gender_mf', 'wind', 'category', 'min', 'year', 'elapsedyrs', 'source']\n    df = df.dropna(subset=required_cols)\n\n    # Rename 'min' to avoid collision with Python built-in; keep original values\n    df['min_pressure'] = df['min']\n\n    # Ensure numeric types where appropriate\n    df['alldeaths'] = pd.to_numeric(df['alldeaths'], errors='coerce')\n    df['masfem'] = pd.to_numeric(df['masfem'], errors='coerce')\n    df['gender_mf'] = pd.to_numeric(df['gender_mf'], errors='coerce').astype(int)\n    df['wind'] = pd.to_numeric(df['wind'], errors='coerce')\n    df['category'] = pd.to_numeric(df['category'], errors='coerce')\n    df['min_pressure'] = pd.to_numeric(df['min_pressure'], errors='coerce')\n    df['year'] = pd.to_numeric(df['year'], errors='coerce')\n    df['elapsedyrs'] = pd.to_numeric(df['elapsedyrs'], errors='coerce')\n\n    # Drop rows that became NA after coercion\n    df = df.dropna(subset=['alldeaths', 'masfem', 'gender_mf', 'wind', 'category', 'min_pressure', 'year', 'elapsedyrs', 'source'])\n\n    # ----------------------\n    # Derived / transformed columns\n    # ----------------------\n    # Standardize masfem so coefficients are interpretable (z-score)\n    df['masfem_z'] = (df['masfem'] - df['masfem'].mean()) / (df['masfem'].std(ddof=0) if df['masfem'].std(ddof=0) != 0 else 1.0)\n\n    # Keep alldeaths as count for count modeling; also create log version for diagnostics/robustness\n    df['alldeaths_log1p'] = np.log1p(df['alldeaths'])\n\n    # Make sure 'source' is a categorical variable for modeling with C(source)\n    df['source'] = df['source'].astype('category')\n\n    # Optional: create an indicator for extremely high-fatality outliers for sensitivity checks\n    df['alldeaths_outlier'] = (df['alldeaths'] > df['alldeaths'].quantile(0.99)).astype(int)\n\n    # Finalize: keep only columns that will be used in the model and useful diagnostics\n    keep_cols = ['alldeaths', 'alldeaths_log1p', 'masfem', 'masfem_z', 'gender_mf', 'wind', 'category', 'min_pressure', 'year', 'elapsedyrs', 'source', 'alldeaths_outlier']\n    df = df[keep_cols]\n\n    return df\n",
  "m_code": "def model(df: pd.DataFrame) -> Any:\n    import statsmodels.formula.api as smf\n    import statsmodels.api as sm\n\n    # Build formula: negative binomial GLM with categorical source control\n    formula = 'alldeaths ~ masfem_z + gender_mf + wind + category + min_pressure + year + elapsedyrs + C(source)'\n\n    # Fit Negative Binomial GLM to account for over-dispersed count data\n    # Using statsmodels' GLM with NegativeBinomial family\n    nb_model = smf.glm(formula=formula, data=df, family=sm.families.NegativeBinomial())\n    results = nb_model.fit()\n\n    # Return the fitted results object. The caller can call .summary() or inspect params, conf_int, etc.\n    return results\n"
}
